#include <stdio.h>
#include <stdlib.h>
int cmp(const void*a,const void*b){return *(int*)a-*(int*)b;}
int main(void){int n,r[100],head,size,dir,total=0;printf("Requests and disk size: ");scanf("%d%d",&n,&size);if(n<1||n>100||size<2)return 1;printf("Request queue: ");for(int i=0;i<n;i++)scanf("%d",&r[i]);printf("Initial head and direction (0=left, 1=right): ");scanf("%d%d",&head,&dir);qsort(r,n,sizeof(int),cmp);printf("Seek sequence: %d",head);if(dir){for(int i=0;i<n;i++)if(r[i]>=head){total+=abs(head-r[i]);head=r[i];printf(" -> %d",head);}total+=abs(head-(size-1));head=size-1;printf(" -> %d",head);for(int i=n-1;i>=0;i--)if(r[i]<head){total+=abs(head-r[i]);head=r[i];printf(" -> %d",head);}}else{for(int i=n-1;i>=0;i--)if(r[i]<=head){total+=abs(head-r[i]);head=r[i];printf(" -> %d",head);}total+=head;head=0;printf(" -> 0");for(int i=0;i<n;i++)if(r[i]>head){total+=abs(head-r[i]);head=r[i];printf(" -> %d",head);}}printf("\nTotal head movement = %d\n",total);return 0;}
